INSERT INTO _a1_084_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=20)=0 AND (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=21)=0 AND (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=22)=0 AND (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=23)=0 AND (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=24)=0 THEN 1 ELSE 0 END;
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 20, 'Погода сьогодні', '["Сьогодні в нашому маленькому місті тепло, і люди гуляють біля річки. Небо синє. На небі немає хмар, і сонце світить над будинками. Біля парку жінка веде маленьку дівчинку до води. На дівчинці біла сорочка, а на жінці теплий светр. Вони повільно йдуть і говорять про школу.","У парку діти грають у м''яч на великій зеленій траві. Поруч стоїть старий велосипед, а біля нього лежить рюкзак. Спочатку хлопець грає з друзями, потім сідає біля річки. Він відпочиває. На воді світить сонце."]', 1, 1, 20) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 20), 1, 'Яке сьогодні небо?', 'Синє', '["Сіре","Біле","Червоне"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 20), 2, 'Кого веде жінка?', 'Дівчинку', '["Хлопця","Бабусю","Друга"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 20), 3, 'Що на жінці?', 'Теплий светр', '["Біла сорочка","Синя шапка","Червона куртка"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 20), 4, 'Що хлопець робить після гри?', 'Сідає біля річки', '["Іде до магазину","Читає в школі","Шукає велосипед"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 20), 5, 'Де світить сонце в кінці?', 'На воді', '["На книжці","На столі","На ліжку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 21, 'Пори року', '["Біля нашого будинку росте велике дерево. Узимку на його гілках лежить білий сніг. Листя немає. Люди йдуть до магазину в теплих куртках і шапках. Навесні на дереві знову є маленьке зелене листя. Біля будинку вже тепло, і діти разом грають у м''яч.","Улітку листя велике, а під деревом стоїть лавка. Там сидить бабуся і читає книжку про море. Поруч її онук їсть морозиво і слухає тиху музику. Восени листя жовте і червоне, а на вулиці холодно. Діти йдуть до школи і несуть книжки в рюкзаках.","Дерево весь рік стоїть біля нашого будинку. Дерево поруч. Кожна пора року має свої кольори."]', 1, 1, 21) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 21), 1, 'Що на гілках узимку?', 'Білий сніг', '["Жовте листя","Червоні квіти","Зелені яблука"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 21), 2, 'Яке листя навесні?', 'Маленьке зелене', '["Велике жовте","Маленьке червоне","Велике біле"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 21), 3, 'Хто читає влітку?', 'Бабуся', '["Онук","Дівчинка","Учитель"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 21), 4, 'Куди діти йдуть восени?', 'До школи', '["До моря","До річки","До парку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 21), 5, 'Де дерево взимку й улітку?', 'Біля будинку', '["Біля школи","Біля річки","Біля магазину"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 22, 'Мій одяг', '["Мій одяг лежить у великій шафі біля ліжка. Уранці я відкриваю двері шафи і вибираю речі для роботи. Тут є сині штани, біла сорочка і сірий светр. Я працюю в офісі біля парку. До роботи йду пішки.","Сьогодні холодно. На сорочку я одягаю теплий светр, а потім куртку. Беру ключі. Біля дверей стоїть моє взуття, а на полиці лежить шапка. Я дивлюся в дзеркало і поправляю светр.","Це мій улюблений светр із великими м''якими рукавами. Увечері я знову ношу його вдома. Сідаю на диван і беру книжку. Мої руки в теплих рукавах."]', 1, 1, 22) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 22), 1, 'Де лежить одяг?', 'У шафі', '["На дивані","Під столом","У сумці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 22), 2, 'Де працює авторка?', 'В офісі', '["У школі","У магазині","У парку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 22), 3, 'Що авторка одягає на сорочку?', 'Светр', '["Шапку","Штани","Взуття"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 22), 4, 'Що вона бере після куртки?', 'Ключі', '["Книжку","Чашку","Телефон"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 22), 5, 'Які рукави у светра?', 'Великі й м''які', '["Малі й холодні","Нові й білі","Сині й короткі"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 23, 'Кольори навколо мене', '["З вікна своєї кімнати я бачу синє небо і зелене дерево. Біля вікна стоїть мій стіл для роботи. На столі біла лампа, а поруч червоний зошит. Я беру зошит і пишу кілька слів про свій день. Потім дивлюся на жовті квіти біля книжок. Тут світло.","Увечері я сиджу на кухні, а сестра готує чай. Переді мною синя чашка, і біля неї синій олівець. Синій — мій улюблений колір. Спочатку я п''ю чай, потім малюю море. Уже тихо. На папері синє море."]', 1, 1, 23) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 23), 1, 'Що автор бачить із вікна?', 'Небо і дерево', '["Море і човен","Магазин і школу","Річку і міст"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 23), 2, 'Яка лампа на столі?', 'Біла', '["Синя","Зелена","Жовта"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 23), 3, 'Які квіти біля книжок?', 'Жовті', '["Червоні","Білі","Сині"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 23), 4, 'Який колір автор любить?', 'Синій', '["Білий","Жовтий","Червоний"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 23), 5, 'Що автор робить після чаю?', 'Малює море', '["Пише в зошиті","Читає книжку","Готує вечерю"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 24, 'Котра година?', '["О сьомій годині дзвонить будильник біля мого ліжка. Я встаю. На кухні висить великий годинник, і я часто дивлюся на нього. О восьмій я снідаю, а потім шукаю ключі від офісу. Уже пізно. Я майже запізнююся на роботу, тому швидко беру сумку.","Робота починається о дев''ятій, і я вже сиджу за столом. О першій годині обідаю з подругою біля роботи. Увечері вдома заряджаю телефон і читаю кілька сторінок. Потім я вимикаю лампу і ставлю будильник біля ліжка. О десятій я лягаю спати."]', 1, 1, 24) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 24), 1, 'Де висить годинник?', 'На кухні', '["В офісі","У коридорі","Біля ліжка"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 24), 2, 'Що авторка шукає після їжі?', 'Ключі від офісу', '["Свою книжку","Новий телефон","Теплий светр"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 24), 3, 'Коли починається робота?', 'О дев''ятій', '["О сьомій","О восьмій","О першій"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 24), 4, 'З ким авторка обідає?', 'З подругою', '["З мамою","Із сестрою","З бабусею"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 24), 5, 'Коли авторка лягає спати?', 'О десятій', '["О першій","О сьомій","О дев''ятій"]');
